/**
 * The shape of a pinned SimulationCraft enchant/gem use-effect artifact, and a
 * runtime validator for it.
 *
 * Generated by `scripts/authority/extract-simc-enchant-effects.mjs` from one
 * exact SimulationCraft commit and committed. Nothing here reaches the network.
 *
 * THE ONE FACT THIS DATA EXISTS FOR
 *
 * Whether an enchant or gem on a worn item creates a `use_item` sub-action.
 * `use_items` with no `slots=` builds one for every worn slot carrying a
 * SPECIAL_EFFECT_USE from the item, a gem, OR an enchant
 * (`use_items_t::create_use_subactions`). The item-effect artifact answers
 * the item source; this artifact answers the other two, so that "exactly
 * these slots produce a sub-action" is a claim over every source and not a
 * hope about two of them.
 *
 * `createsUseEffect` is the machine reading of the row under the hand-reviewed
 * rule in `enchantSemantics`: a USE effect exists only for an `ench_type` of
 * ITEM_ENCHANTMENT_USE_SPELL with a non-zero `ench_prop`
 * (`enchant::initialize_item_enchant`). The raw types and props are kept so
 * the reading can be re-checked without the extractor.
 *
 * THE UNIVERSE CENSUS (M10-C2). `useEffectUniverse` is every row of the
 * pinned enchant table that creates a use effect — not just the ones a subject
 * wears — with the placement the pinned tables can state for each: temporary
 * (`temporary_enchant.inc`), permanent with an inventory-type mask
 * (`permanent_enchant.inc`), or gem-borne (`id_gem`). It exists so an OMITTED
 * gear key can be closed by exclusion rather than by assumption: an omitted
 * `temporaryEnchant` is irrelevant when no temporary enchant in the build
 * creates a use effect; an omitted `permanentEnchant` on a slot is irrelevant
 * only when every use-producing row has a pinned placement AND none admits
 * that inventory type. The summary counts are re-derived here from the rows,
 * so an artifact whose summary disagrees with its own rows is refused.
 *
 * CLASS-NEUTRAL. Nothing here knows which specialization wears the gear.
 */

export const SUPPORTED_ENCHANT_EFFECT_ARTIFACT_VERSION = 1;
export const ENCHANT_DATA_METHOD = "MACHINE_EXTRACTED_DBC_RECORD";
export const ENCHANT_SEMANTICS_METHOD = "HAND_REVIEWED_CPP_ENCHANT_SEMANTICS";

export interface EnchantEffectArtifactSource {
  readonly path: string;
  readonly sha256: string;
  readonly byteLength: number;
}

export interface EnchantEffectArtifactProvenance {
  readonly repository: string;
  readonly commitSha: string;
  readonly sources: readonly EnchantEffectArtifactSource[];
  readonly clientDataWowVersion: string;
  readonly clientDataHotfixDate: string;
  readonly clientDataHotfixBuild: number;
  readonly clientDataHotfixHash: string;
  readonly extractor: string;
  readonly extractorVersion: number;
  readonly extractedOn: string;
  readonly method: typeof ENCHANT_DATA_METHOD;
  /** The verified value of ITEM_ENCHANTMENT_USE_SPELL at the pinned commit. */
  readonly useSpellEnchantType: number;
}

export interface EnchantSemanticsCheck {
  readonly claim: string;
  readonly symbol: string;
  readonly lines: string;
  readonly detail: string;
}

export interface EnchantSemantics {
  readonly method: typeof ENCHANT_SEMANTICS_METHOD;
  readonly sourcePath: string;
  readonly sourceSha256: string;
  readonly reviewedOn: string;
  readonly checks: readonly EnchantSemanticsCheck[];
}

export interface EnchantEffectRow {
  readonly enchantId: number;
  readonly nameEn: string;
  readonly enchTypes: readonly number[];
  readonly enchProps: readonly number[];
  readonly createsUseEffect: boolean;
  readonly why: string;
}

export interface GemEffectRow {
  readonly itemId: number;
  readonly displayNameEn: string;
  readonly gemPropertiesId: number;
  readonly enchant: EnchantEffectRow;
}

export interface PermanentEnchantPlacement {
  readonly itemClass: number;
  /** Bit `1 << inventoryType` set when the enchant may sit on that inventory type. */
  readonly maskInventoryType: number;
  readonly maskItemSubclass: number;
}

/** One effect row of a driver or trigger spell, verbatim from the pinned effect table. */
export interface UseEffectSpellEffect {
  readonly index: number;
  readonly type: number;
  readonly subtype: number;
  readonly miscValue: number;
  readonly triggerSpellId: number;
}

/** The scalar facts of one spell the use-effect question reads, verbatim from `sc_spell_data.inc`. */
export interface UseEffectSpell {
  readonly spellId: number;
  readonly nameEn: string;
  readonly cooldownMs: number;
  readonly internalCooldownMs: number;
  readonly categoryCooldownMs: number;
  readonly category: number;
  readonly charges: number;
  readonly chargeCooldownMs: number;
  readonly gcdMs: number;
  readonly castTimeMs: number;
  readonly maxTargets: number;
  readonly effects: readonly UseEffectSpellEffect[];
}

/**
 * SimulationCraft's GENERIC reading of a use effect (special_effect.cpp): what
 * buff and what action `use_item_t::init` would build from the driver's
 * trigger spell, the cast time that action would carry, and the cooldown
 * `special_effect_t::cooldown()` resolves to. Derived by the extractor and
 * RE-DERIVED by this validator from the effect rows it ships with.
 */
export interface GenericUseEffectReading {
  readonly buffType: "STAT" | "ABSORB" | "NONE";
  readonly actionType: "SPELL" | "HEAL" | "ATTACK" | "RESOURCE" | "NONE";
  readonly actionCastTimeMs: number | null;
  readonly effectiveCooldownMs: number;
}

export type UseEffectDriver =
  | {
      /** The USE spell exists in the pinned spell table. */
      readonly spellId: number;
      readonly resolved: true;
      readonly driver: UseEffectSpell;
      /** The trigger spell the generic rules read, when it differs from the driver. */
      readonly trigger: UseEffectSpell | null;
      /** The `unique_gear*.cpp` files registering a custom handler for this driver. Non-empty = SCRIPTED. */
      readonly scriptedIn: readonly string[];
      readonly generic: GenericUseEffectReading;
    }
  | {
      /** The USE spell is ABSENT from the pinned spell table. Nothing about its behaviour is derivable. */
      readonly spellId: number;
      readonly resolved: false;
    };

export interface UseProducingEnchantRow {
  readonly enchantId: number;
  readonly nameEn: string;
  readonly enchTypes: readonly number[];
  readonly enchProps: readonly number[];
  readonly spellId: number;
  readonly reqSkill: number;
  readonly reqSkillValue: number;
  readonly gemItemId: number | null;
  /** Reached through a gem: the row's own `id_gem`, or any gem property row pointing at it. */
  readonly gemBorne: boolean;
  readonly temporary: boolean;
  readonly permanent: readonly PermanentEnchantPlacement[] | null;
  /** False: nothing pinned says where this row can sit. It keeps every slot open. */
  readonly placementKnown: boolean;
  /** One entry per USE_SPELL effect of the row (M10-C3). */
  readonly drivers: readonly UseEffectDriver[];
}

export interface UseEffectUniverse {
  readonly method: typeof ENCHANT_DATA_METHOD;
  readonly totalEnchantRows: number;
  readonly temporaryEnchantRows: number;
  readonly permanentEnchantIds: number;
  readonly useProducingRows: readonly UseProducingEnchantRow[];
  readonly temporaryUseProducingCount: number;
  readonly gemBorneUseProducingCount: number;
  readonly permanentUseProducingInventoryTypeMask: number;
  readonly unplacedUseProducingCount: number;
  /** The enumerator values the generic rules were applied with, as read from data_enums.hh. */
  readonly genericRuleEnumerators: Readonly<Record<string, number>>;
  readonly scriptedDriverCount: number;
  readonly unresolvedDriverCount: number;
}

/** The enumerators the generic reading is re-derived with. Every one must be present in the artifact. */
export const GENERIC_RULE_ENUMERATOR_NAMES = [
  "E_SCHOOL_DAMAGE",
  "E_DUMMY",
  "E_APPLY_AURA",
  "E_HEALTH_LEECH",
  "E_HEAL",
  "E_ENERGIZE",
  "E_WEAPON_PERCENT_DAMAGE",
  "E_WEAPON_DAMAGE",
  "E_TRIGGER_SPELL",
  "A_PERIODIC_DAMAGE",
  "A_PERIODIC_HEAL",
  "A_MOD_DAMAGE_DONE",
  "A_MOD_RESISTANCE",
  "A_PERIODIC_ENERGIZE",
  "A_MOD_STAT",
  "A_MOD_INCREASE_HEALTH",
  "A_PERIODIC_LEECH",
  "A_SCHOOL_ABSORB",
  "A_MOD_ATTACK_POWER",
  "A_MOD_RANGED_ATTACK_POWER",
  "A_MOD_RATING",
  "A_MOD_INCREASE_HEALTH_2",
  "A_MOD_BONUS_ARMOR",
] as const;

/**
 * SimulationCraft's generic use-effect reading, re-derived from effect rows
 * (special_effect.cpp `stat_buff_type`, `is_absorb_buff`,
 * `is_offensive_spell_action`, `is_heal_action`, `is_attack_action`,
 * `is_resource_action`, and `cooldown()`). Exported so a test can apply it to
 * a hand-built row and so the validator can refuse an artifact whose shipped
 * reading disagrees with its own rows.
 */
export function genericUseEffectReading(
  driver: UseEffectSpell,
  trigger: UseEffectSpell | null,
  E: Readonly<Record<string, number>>,
): GenericUseEffectReading {
  const read = trigger ?? driver;
  const effects = read.effects;
  const statSubtypes = [
    E.A_MOD_STAT,
    E.A_MOD_RATING,
    E.A_MOD_INCREASE_HEALTH_2,
    E.A_MOD_INCREASE_HEALTH,
    E.A_MOD_RESISTANCE,
    E.A_MOD_ATTACK_POWER,
    E.A_MOD_RANGED_ATTACK_POWER,
    E.A_MOD_BONUS_ARMOR,
  ];
  const aura = (effect: UseEffectSpellEffect) => effect.type === E.E_APPLY_AURA;
  const isStat = effects.some(
    (effect) =>
      aura(effect) &&
      (statSubtypes.includes(effect.subtype) ||
        (effect.subtype === E.A_MOD_DAMAGE_DONE && (effect.miscValue & 0x7e) !== 0)),
  );
  const isAbsorb = effects.some((effect) => aura(effect) && effect.subtype === E.A_SCHOOL_ABSORB);
  const offensive = effects.some(
    (effect) =>
      effect.type === E.E_SCHOOL_DAMAGE ||
      effect.type === E.E_HEALTH_LEECH ||
      (aura(effect) && (effect.subtype === E.A_PERIODIC_DAMAGE || effect.subtype === E.A_PERIODIC_LEECH)),
  );
  const heal = effects.some(
    (effect) => effect.type === E.E_HEAL || (aura(effect) && effect.subtype === E.A_PERIODIC_HEAL),
  );
  const attack = effects.some(
    (effect) => effect.type === E.E_WEAPON_DAMAGE || effect.type === E.E_WEAPON_PERCENT_DAMAGE,
  );
  const resource = effects.some(
    (effect) => effect.type === E.E_ENERGIZE || (aura(effect) && effect.subtype === E.A_PERIODIC_ENERGIZE),
  );
  return {
    buffType: isStat ? "STAT" : isAbsorb ? "ABSORB" : "NONE",
    actionType: offensive ? "SPELL" : heal ? "HEAL" : attack ? "ATTACK" : resource ? "RESOURCE" : "NONE",
    actionCastTimeMs: read.castTimeMs,
    effectiveCooldownMs:
      driver.cooldownMs > 0
        ? driver.cooldownMs
        : driver.internalCooldownMs > 0
          ? driver.internalCooldownMs
          : 0,
  };
}

export interface EnchantEffectArtifact {
  readonly artifactVersion: number;
  readonly datasetId: string;
  readonly artifactRevision: string;
  readonly provenance: EnchantEffectArtifactProvenance;
  readonly enchantSemantics: EnchantSemantics;
  readonly useEffectUniverse: UseEffectUniverse;
  readonly enchants: readonly EnchantEffectRow[];
  readonly gems: readonly GemEffectRow[];
}

export type EnchantEffectArtifactValidationReason =
  | "NOT_AN_OBJECT"
  | "UNSUPPORTED_ARTIFACT_VERSION"
  | "MISSING_DATASET_ID"
  | "INVALID_PROVENANCE"
  | "INVALID_ENCHANT_SEMANTICS"
  | "INVALID_ENCHANT_ROW"
  | "INVALID_GEM_ROW"
  | "USE_EFFECT_READING_MISMATCH"
  | "DUPLICATE_ENCHANT"
  | "DUPLICATE_GEM"
  | "INVALID_UNIVERSE"
  | "UNIVERSE_SUMMARY_MISMATCH"
  | "DRIVER_READING_MISMATCH";

export type EnchantEffectArtifactValidation =
  | { readonly ok: true; readonly artifact: EnchantEffectArtifact }
  | { readonly ok: false; readonly reason: EnchantEffectArtifactValidationReason; readonly detail: string };

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
function str(record: Record<string, unknown>, key: string): string | null {
  const value = record[key];
  return typeof value === "string" && value.length > 0 ? value : null;
}
function nonNegativeInt(record: Record<string, unknown>, key: string): number | null {
  const value = record[key];
  return typeof value === "number" && Number.isInteger(value) && value >= 0 ? value : null;
}
function intArray(value: unknown, length: number): readonly number[] | null {
  if (!Array.isArray(value) || value.length !== length) return null;
  const out: number[] = [];
  for (const entry of value) {
    if (typeof entry !== "number" || !Number.isInteger(entry)) return null;
    out.push(entry);
  }
  return out;
}
function invalid(
  reason: EnchantEffectArtifactValidationReason,
  detail: string,
): EnchantEffectArtifactValidation {
  return { ok: false, reason, detail };
}

function validateSources(value: unknown): readonly EnchantEffectArtifactSource[] | null {
  if (!Array.isArray(value) || value.length === 0) return null;
  const out: EnchantEffectArtifactSource[] = [];
  for (const entry of value) {
    if (!isRecord(entry)) return null;
    const path = str(entry, "path");
    const sha256 = str(entry, "sha256");
    const byteLength = nonNegativeInt(entry, "byteLength");
    if (path === null || sha256 === null || !/^[0-9a-f]{64}$/.test(sha256) || byteLength === null)
      return null;
    out.push({ path, sha256, byteLength });
  }
  return out;
}

function validateProvenance(value: unknown): EnchantEffectArtifactProvenance | null {
  if (!isRecord(value)) return null;
  const sources = validateSources(value.sources);
  const repository = str(value, "repository");
  const commitSha = str(value, "commitSha");
  const clientDataWowVersion = str(value, "clientDataWowVersion");
  const clientDataHotfixDate = str(value, "clientDataHotfixDate");
  const clientDataHotfixBuild = nonNegativeInt(value, "clientDataHotfixBuild");
  const clientDataHotfixHash = str(value, "clientDataHotfixHash");
  const extractor = str(value, "extractor");
  const extractorVersion = nonNegativeInt(value, "extractorVersion");
  const extractedOn = str(value, "extractedOn");
  const useSpellEnchantType = nonNegativeInt(value, "useSpellEnchantType");
  if (
    sources === null ||
    repository === null ||
    commitSha === null ||
    !/^[0-9a-f]{40}$/.test(commitSha) ||
    clientDataWowVersion === null ||
    clientDataHotfixDate === null ||
    clientDataHotfixBuild === null ||
    clientDataHotfixHash === null ||
    extractor === null ||
    extractorVersion === null ||
    extractedOn === null ||
    value.method !== ENCHANT_DATA_METHOD ||
    useSpellEnchantType === null
  ) {
    return null;
  }
  return {
    repository,
    commitSha,
    sources,
    clientDataWowVersion,
    clientDataHotfixDate,
    clientDataHotfixBuild,
    clientDataHotfixHash,
    extractor,
    extractorVersion,
    extractedOn,
    method: ENCHANT_DATA_METHOD,
    useSpellEnchantType,
  };
}

function validateSemantics(value: unknown): EnchantSemantics | null {
  if (!isRecord(value) || value.method !== ENCHANT_SEMANTICS_METHOD) return null;
  const sourcePath = str(value, "sourcePath");
  const sourceSha256 = str(value, "sourceSha256");
  const reviewedOn = str(value, "reviewedOn");
  if (
    sourcePath === null ||
    sourceSha256 === null ||
    !/^[0-9a-f]{64}$/.test(sourceSha256) ||
    reviewedOn === null
  ) {
    return null;
  }
  if (!Array.isArray(value.checks) || value.checks.length === 0) return null;
  const checks: EnchantSemanticsCheck[] = [];
  for (const entry of value.checks) {
    if (!isRecord(entry)) return null;
    const claim = str(entry, "claim");
    const symbol = str(entry, "symbol");
    const lines = str(entry, "lines");
    const detail = str(entry, "detail");
    if (claim === null || symbol === null || lines === null || detail === null) return null;
    checks.push({ claim, symbol, lines, detail });
  }
  return { method: ENCHANT_SEMANTICS_METHOD, sourcePath, sourceSha256, reviewedOn, checks };
}

function validateEnchantRow(value: unknown, useSpellType: number): EnchantEffectRow | "READING" | null {
  if (!isRecord(value)) return null;
  const enchantId = nonNegativeInt(value, "enchantId");
  const nameEn = str(value, "nameEn");
  const enchTypes = intArray(value.enchTypes, 3);
  const enchProps = intArray(value.enchProps, 3);
  const why = str(value, "why");
  if (enchantId === null || nameEn === null || enchTypes === null || enchProps === null || why === null)
    return null;
  if (typeof value.createsUseEffect !== "boolean") return null;
  // The machine reading must agree with the raw row it was read from.
  const expected = enchTypes.some((type, index) => type === useSpellType && enchProps[index] !== 0);
  if (expected !== value.createsUseEffect) return "READING";
  return { enchantId, nameEn, enchTypes, enchProps, createsUseEffect: value.createsUseEffect, why };
}

function validateSpell(value: unknown): UseEffectSpell | null {
  if (!isRecord(value)) return null;
  const spellId = nonNegativeInt(value, "spellId");
  const nameEn = typeof value.nameEn === "string" ? value.nameEn : null;
  const numbers = [
    "cooldownMs",
    "internalCooldownMs",
    "categoryCooldownMs",
    "category",
    "charges",
    "chargeCooldownMs",
    "gcdMs",
    "castTimeMs",
    "maxTargets",
  ] as const;
  const read: Record<string, number> = {};
  for (const key of numbers) {
    const raw = value[key];
    if (typeof raw !== "number" || !Number.isInteger(raw)) return null;
    read[key] = raw;
  }
  if (spellId === null || nameEn === null || !Array.isArray(value.effects)) return null;
  const effects: UseEffectSpellEffect[] = [];
  for (const entry of value.effects) {
    if (!isRecord(entry)) return null;
    const fields = ["index", "type", "subtype", "miscValue", "triggerSpellId"] as const;
    const effect: Record<string, number> = {};
    for (const key of fields) {
      const raw = entry[key];
      if (typeof raw !== "number" || !Number.isInteger(raw)) return null;
      effect[key] = raw;
    }
    effects.push(effect as unknown as UseEffectSpellEffect);
  }
  return { spellId, nameEn, ...(read as Omit<UseEffectSpell, "spellId" | "nameEn" | "effects">), effects };
}

function validateDriver(
  value: unknown,
  E: Readonly<Record<string, number>>,
): UseEffectDriver | "READING" | null {
  if (!isRecord(value)) return null;
  const spellId = nonNegativeInt(value, "spellId");
  if (spellId === null || typeof value.resolved !== "boolean") return null;
  if (!value.resolved) return { spellId, resolved: false };
  const driver = validateSpell(value.driver);
  const trigger = value.trigger === null ? null : validateSpell(value.trigger);
  if (driver === null || trigger === undefined || driver.spellId !== spellId) return null;
  if (!Array.isArray(value.scriptedIn) || !value.scriptedIn.every((entry) => typeof entry === "string"))
    return null;
  if (!isRecord(value.generic)) return null;
  const expected = genericUseEffectReading(driver, trigger, E);
  const generic = value.generic;
  if (
    generic.buffType !== expected.buffType ||
    generic.actionType !== expected.actionType ||
    generic.actionCastTimeMs !== expected.actionCastTimeMs ||
    generic.effectiveCooldownMs !== expected.effectiveCooldownMs
  ) {
    return "READING";
  }
  return {
    spellId,
    resolved: true,
    driver,
    trigger,
    scriptedIn: value.scriptedIn as readonly string[],
    generic: expected,
  };
}

function validateUniverseRow(
  value: unknown,
  useSpellType: number,
  E: Readonly<Record<string, number>>,
): UseProducingEnchantRow | "READING" | null {
  if (!isRecord(value)) return null;
  const enchantId = nonNegativeInt(value, "enchantId");
  const nameEn = str(value, "nameEn");
  const enchTypes = intArray(value.enchTypes, 3);
  const enchProps = intArray(value.enchProps, 3);
  const spellId = nonNegativeInt(value, "spellId");
  const reqSkill = nonNegativeInt(value, "reqSkill");
  const reqSkillValue = nonNegativeInt(value, "reqSkillValue");
  if (
    enchantId === null ||
    nameEn === null ||
    enchTypes === null ||
    enchProps === null ||
    spellId === null ||
    reqSkill === null ||
    reqSkillValue === null
  ) {
    return null;
  }
  // Every universe row must actually be use-producing under the pinned rule.
  if (!enchTypes.some((type, index) => type === useSpellType && enchProps[index] !== 0)) return null;
  const gemItemId = value.gemItemId === null ? null : nonNegativeInt(value, "gemItemId");
  if (gemItemId === undefined || gemItemId === 0) return null;
  if (
    typeof value.temporary !== "boolean" ||
    typeof value.placementKnown !== "boolean" ||
    typeof value.gemBorne !== "boolean"
  ) {
    return null;
  }
  // A row with its own gem id is gem-borne by definition.
  if (gemItemId !== null && !value.gemBorne) return null;
  if (!Array.isArray(value.drivers) || value.drivers.length === 0) return null;
  const drivers: UseEffectDriver[] = [];
  for (const entry of value.drivers) {
    const driver = validateDriver(entry, E);
    if (driver === null) return null;
    if (driver === "READING") return "READING";
    drivers.push(driver);
  }
  // Exactly one driver per USE_SPELL effect, in effect order.
  const useSpellIds = enchTypes
    .map((type, index) => (type === useSpellType && enchProps[index] !== 0 ? enchProps[index] : null))
    .filter((id): id is number => id !== null);
  if (JSON.stringify(drivers.map((driver) => driver.spellId)) !== JSON.stringify(useSpellIds)) return null;
  let permanent: PermanentEnchantPlacement[] | null = null;
  if (value.permanent !== null) {
    if (!Array.isArray(value.permanent) || value.permanent.length === 0) return null;
    permanent = [];
    for (const entry of value.permanent) {
      if (!isRecord(entry)) return null;
      const itemClass = entry.itemClass;
      const maskInventoryType = nonNegativeInt(entry, "maskInventoryType");
      const maskItemSubclass = entry.maskItemSubclass;
      if (
        typeof itemClass !== "number" ||
        !Number.isInteger(itemClass) ||
        maskInventoryType === null ||
        typeof maskItemSubclass !== "number" ||
        !Number.isInteger(maskItemSubclass)
      ) {
        return null;
      }
      permanent.push({ itemClass, maskInventoryType, maskItemSubclass });
    }
  }
  // `placementKnown` is derived, and must agree with the row it summarises.
  if (value.placementKnown !== (value.temporary || permanent !== null || value.gemBorne)) return null;
  return {
    enchantId,
    nameEn,
    enchTypes,
    enchProps,
    spellId,
    reqSkill,
    reqSkillValue,
    gemItemId,
    gemBorne: value.gemBorne,
    temporary: value.temporary,
    permanent,
    placementKnown: value.placementKnown,
    drivers,
  };
}

function validateUniverse(
  value: unknown,
  useSpellType: number,
): UseEffectUniverse | "SUMMARY" | "READING" | null {
  if (!isRecord(value) || value.method !== ENCHANT_DATA_METHOD) return null;
  if (!isRecord(value.genericRuleEnumerators)) return null;
  const E: Record<string, number> = {};
  for (const name of GENERIC_RULE_ENUMERATOR_NAMES) {
    const raw = value.genericRuleEnumerators[name];
    if (typeof raw !== "number" || !Number.isInteger(raw)) return null;
    E[name] = raw;
  }
  const scriptedDriverCount = nonNegativeInt(value, "scriptedDriverCount");
  const unresolvedDriverCount = nonNegativeInt(value, "unresolvedDriverCount");
  if (scriptedDriverCount === null || unresolvedDriverCount === null) return null;
  const totalEnchantRows = nonNegativeInt(value, "totalEnchantRows");
  const temporaryEnchantRows = nonNegativeInt(value, "temporaryEnchantRows");
  const permanentEnchantIds = nonNegativeInt(value, "permanentEnchantIds");
  const temporaryUseProducingCount = nonNegativeInt(value, "temporaryUseProducingCount");
  const gemBorneUseProducingCount = nonNegativeInt(value, "gemBorneUseProducingCount");
  const permanentUseProducingInventoryTypeMask = nonNegativeInt(
    value,
    "permanentUseProducingInventoryTypeMask",
  );
  const unplacedUseProducingCount = nonNegativeInt(value, "unplacedUseProducingCount");
  if (
    totalEnchantRows === null ||
    temporaryEnchantRows === null ||
    permanentEnchantIds === null ||
    temporaryUseProducingCount === null ||
    gemBorneUseProducingCount === null ||
    permanentUseProducingInventoryTypeMask === null ||
    unplacedUseProducingCount === null ||
    !Array.isArray(value.useProducingRows)
  ) {
    return null;
  }
  // A census over an empty table, or one that found nothing to place against, is not a census.
  if (totalEnchantRows === 0 || temporaryEnchantRows === 0 || permanentEnchantIds === 0) return null;
  const rows: UseProducingEnchantRow[] = [];
  const seen = new Set<number>();
  for (const entry of value.useProducingRows) {
    const row = validateUniverseRow(entry, useSpellType, E);
    if (row === "READING") return "READING";
    if (row === null || seen.has(row.enchantId)) return null;
    seen.add(row.enchantId);
    rows.push(row);
  }
  if (rows.length > totalEnchantRows) return null;
  // INDEPENDENT re-derivation of every summary from the rows.
  let mask = 0;
  for (const row of rows) for (const entry of row.permanent ?? []) mask |= entry.maskInventoryType;
  if (
    temporaryUseProducingCount !== rows.filter((row) => row.temporary).length ||
    gemBorneUseProducingCount !== rows.filter((row) => row.gemBorne).length ||
    permanentUseProducingInventoryTypeMask !== mask ||
    unplacedUseProducingCount !== rows.filter((row) => !row.placementKnown).length ||
    scriptedDriverCount !==
      rows.filter((row) => row.drivers.some((driver) => driver.resolved && driver.scriptedIn.length > 0))
        .length ||
    unresolvedDriverCount !== rows.filter((row) => row.drivers.some((driver) => !driver.resolved)).length
  ) {
    return "SUMMARY";
  }
  return {
    method: ENCHANT_DATA_METHOD,
    totalEnchantRows,
    temporaryEnchantRows,
    permanentEnchantIds,
    useProducingRows: rows,
    temporaryUseProducingCount,
    gemBorneUseProducingCount,
    permanentUseProducingInventoryTypeMask,
    unplacedUseProducingCount,
    genericRuleEnumerators: E,
    scriptedDriverCount,
    unresolvedDriverCount,
  };
}

export function validateEnchantEffectArtifact(value: unknown): EnchantEffectArtifactValidation {
  if (!isRecord(value)) return invalid("NOT_AN_OBJECT", "artifact root is not an object");
  if (value.artifactVersion !== SUPPORTED_ENCHANT_EFFECT_ARTIFACT_VERSION) {
    return invalid(
      "UNSUPPORTED_ARTIFACT_VERSION",
      `artifactVersion ${JSON.stringify(value.artifactVersion)} is not ${String(SUPPORTED_ENCHANT_EFFECT_ARTIFACT_VERSION)}`,
    );
  }
  const datasetId = str(value, "datasetId");
  const artifactRevision = str(value, "artifactRevision");
  if (datasetId === null || artifactRevision === null)
    return invalid("MISSING_DATASET_ID", "datasetId/artifactRevision");
  const provenance = validateProvenance(value.provenance);
  if (provenance === null) return invalid("INVALID_PROVENANCE", "provenance is incomplete");
  const enchantSemantics = validateSemantics(value.enchantSemantics);
  if (enchantSemantics === null)
    return invalid("INVALID_ENCHANT_SEMANTICS", "enchantSemantics is incomplete");
  const useEffectUniverse = validateUniverse(value.useEffectUniverse, provenance.useSpellEnchantType);
  if (useEffectUniverse === null) return invalid("INVALID_UNIVERSE", "useEffectUniverse is incomplete");
  if (useEffectUniverse === "SUMMARY") {
    return invalid("UNIVERSE_SUMMARY_MISMATCH", "useEffectUniverse summary counts disagree with its rows");
  }
  if (useEffectUniverse === "READING") {
    return invalid(
      "DRIVER_READING_MISMATCH",
      "a driver's shipped generic reading disagrees with its effect rows",
    );
  }

  if (!Array.isArray(value.enchants)) return invalid("INVALID_ENCHANT_ROW", "enchants is not an array");
  const enchants: EnchantEffectRow[] = [];
  const seenEnchants = new Set<number>();
  for (const entry of value.enchants) {
    const row = validateEnchantRow(entry, provenance.useSpellEnchantType);
    if (row === null) return invalid("INVALID_ENCHANT_ROW", `enchant row ${JSON.stringify(entry)}`);
    if (row === "READING") return invalid("USE_EFFECT_READING_MISMATCH", `enchant ${JSON.stringify(entry)}`);
    if (seenEnchants.has(row.enchantId)) return invalid("DUPLICATE_ENCHANT", String(row.enchantId));
    seenEnchants.add(row.enchantId);
    enchants.push(row);
  }

  if (!Array.isArray(value.gems)) return invalid("INVALID_GEM_ROW", "gems is not an array");
  const gems: GemEffectRow[] = [];
  const seenGems = new Set<number>();
  for (const entry of value.gems) {
    if (!isRecord(entry)) return invalid("INVALID_GEM_ROW", "gem row is not an object");
    const itemId = nonNegativeInt(entry, "itemId");
    const displayNameEn = str(entry, "displayNameEn");
    const gemPropertiesId = nonNegativeInt(entry, "gemPropertiesId");
    if (itemId === null || displayNameEn === null || gemPropertiesId === null) {
      return invalid("INVALID_GEM_ROW", `gem row ${JSON.stringify(entry)}`);
    }
    const enchant = validateEnchantRow(entry.enchant, provenance.useSpellEnchantType);
    if (enchant === null) return invalid("INVALID_GEM_ROW", `gem ${String(itemId)} enchant`);
    if (enchant === "READING") return invalid("USE_EFFECT_READING_MISMATCH", `gem ${String(itemId)}`);
    if (seenGems.has(itemId)) return invalid("DUPLICATE_GEM", String(itemId));
    seenGems.add(itemId);
    gems.push({ itemId, displayNameEn, gemPropertiesId, enchant });
  }

  return {
    ok: true,
    artifact: {
      artifactVersion: SUPPORTED_ENCHANT_EFFECT_ARTIFACT_VERSION,
      datasetId,
      artifactRevision,
      provenance,
      enchantSemantics,
      useEffectUniverse,
      enchants,
      gems,
    },
  };
}

/**
 * What the pinned universe says about a gear row whose enchant/gem keys the
 * log OMITTED. Every answer is a positive exclusion or an explicit "possible";
 * none of them reads the omission itself as a fact.
 */
export interface OmittedKeyVerdicts {
  /** Whether ANY temporary enchant in the build creates a use effect. */
  readonly temporaryUseEnchantPossible: boolean;
  /** Whether a permanent use-producing enchant could sit on this inventory type, and why. */
  readonly permanentUseEnchantPossible: (inventoryType: number) => {
    readonly possible: boolean;
    readonly detail: string;
  };
  /** Whether ANY gem-borne use effect exists in the build. */
  readonly gemBorneUseEffectPossible: boolean;
}

export function omittedKeyVerdictsOf(universe: UseEffectUniverse): OmittedKeyVerdicts {
  return {
    temporaryUseEnchantPossible: universe.temporaryUseProducingCount > 0,
    permanentUseEnchantPossible: (inventoryType) => {
      const bit = 1 << inventoryType;
      const admitted = universe.useProducingRows.filter((row) =>
        (row.permanent ?? []).some((entry) => (entry.maskInventoryType & bit) !== 0),
      );
      if (universe.unplacedUseProducingCount > 0) {
        return {
          possible: true,
          detail:
            `${String(universe.unplacedUseProducingCount)} use-producing enchant row(s) carry no pinned placement ` +
            `and ${String(admitted.length)} permanent row(s) admit inventory type ${String(inventoryType)}`,
        };
      }
      if (admitted.length > 0) {
        return {
          possible: true,
          detail: `${String(admitted.length)} permanent use-producing row(s) admit inventory type ${String(inventoryType)}`,
        };
      }
      return {
        possible: false,
        detail: `every use-producing row has a pinned placement and none admits inventory type ${String(inventoryType)}`,
      };
    },
    gemBorneUseEffectPossible: universe.gemBorneUseProducingCount > 0,
  };
}
